WITH selected AS (SELECT DISTINCT ON (tournament.type) tournament.* FROM public.track_tournament tournament WHERE tournament.type IN (0,1,2) AND tournament.start_at<=clock_timestamp() ORDER BY tournament.type, (tournament.end_at>clock_timestamp()) DESC,tournament.start_at DESC,tournament.id DESC) SELECT jsonb_build_object('tournamentId',selected.id,'tournamentType',selected.type, 'tournamentSlug',selected.slug,'endAt',to_char(selected.end_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'levelName',COALESCE(item.name,'Unknown'), 'imageUrl',NULLIF(item.image_url,''),'entries',(SELECT count(*) FROM public.track_tournament_result result WHERE result.id_tournament=selected.id),'standings',COALESCE((SELECT jsonb_agg( jsonb_build_object('userId',ranked.id_user,'steamName',ranked.steam_name, 'discordId',ranked.discord_id::text,'time',ranked.time,'rank',ranked.rank,'points',ranked.points) ORDER BY ranked.rank,ranked.time,ranked.id_record) FROM (SELECT result.id_user, result.id_record,"user".steam_name,"user".discord_id,result.time,result.rank,result.points FROM public.track_tournament_result result JOIN public."user" ON "user".id=result.id_user WHERE result.id_tournament=selected.id ORDER BY result.rank,result.time,result.id_record LIMIT 3) ranked),'[]'::jsonb)) AS value FROM selected LEFT JOIN LATERAL (SELECT source.name, source.image_url FROM public.level_item source WHERE source.id_level=selected.id_level AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true ORDER BY selected.type
